import * as THREE from './assets/three.module.js';
import {BLOCKS} from './driving.mjs?v=27';
import {PASSENGER_MODELS} from './passengers.mjs?v=27';
export function residentRoutes(){
 const routes=[];for(const b of BLOCKS.filter(b=>b.outer)){const e=14.1;for(let n=0;n<2;n++)routes.push({points:[{x:b.x-e,z:b.z-e},{x:b.x+e,z:b.z-e},{x:b.x+e,z:b.z+e},{x:b.x-e,z:b.z+e}],district:b.district,outer:true,seed:routes.length,direction:n?-1:1});}
 const inner=[[[-50,-44],[-50,-28]],[[-22,-43],[-22,-29]],[[14,-43],[14,-29]],[[50,-44],[50,-28]],[[-50,25],[-50,43]],[[-22,26],[-22,43]],[[14,27],[14,43]],[[50,25],[50,42]],[[-86,-44],[-86,-28]],[[86,-44],[86,-28]],[[-44,-86],[-28,-86]],[[28,86],[44,86]]];
 for(const pair of inner)for(let n=0;n<2;n++)routes.push({points:pair.map(p=>({x:p[0],z:p[1]})),district:'downtown',outer:false,seed:routes.length,direction:n?-1:1});return routes;
}
export function residentPosition(resident,time){const {points,lengths,total,speed,phase,direction}=resident;let d=((phase+time*speed*direction)%total+total)%total;for(let i=0;i<points.length;i++){if(d<=lengths[i]||i===points.length-1){const a=points[i],b=points[(i+1)%points.length],t=d/lengths[i];return{x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t,heading:Math.atan2((b.x-a.x)*direction,(b.z-a.z)*direction)};}d-=lengths[i];}}
export function createCityResidents(templates,world){return residentRoutes().map((route,i)=>{const model=PASSENGER_MODELS[i%PASSENGER_MODELS.length],template=templates['passenger-'+model],root=template.scene.clone(true),group=new THREE.Group();root.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(root),scale=(1.62+(i%5)*.055)/(bounds.max.y-bounds.min.y);root.scale.setScalar(scale);root.position.y=-bounds.min.y*scale;group.add(root);world.add(group);group.visible=false;const mixer=new THREE.AnimationMixer(root),clip=template.animations.find(a=>a.name==='walk'),speed=.78+(i*7%11)*.044,action=clip?mixer.clipAction(clip):null;if(action){action.time=(i*.137)%clip.duration;action.setEffectiveTimeScale(speed/.95).play();}const lengths=route.points.map((p,n)=>Math.hypot(route.points[(n+1)%route.points.length].x-p.x,route.points[(n+1)%route.points.length].z-p.z)),total=lengths.reduce((a,b)=>a+b,0),r={...route,group,root,mixer,model,lengths,total,speed,phase:((i*0.61803398875)%1)*total,shown:false};const p=residentPosition(r,0);group.position.set(p.x,.18,p.z);group.rotation.y=p.heading;return r;});}
export function updateCityResidents(residents,time,dt,focus,maxVisible=48){
 for(const r of residents){const p=residentPosition(r,time);r.group.position.set(p.x,.18,p.z);r.group.rotation.y=p.heading;}
 if(time>=(residents.nextSelection??-1)||Math.hypot(focus.x-(residents.focusX??Infinity),focus.z-(residents.focusZ??Infinity))>15){residents.nextSelection=time+.25;residents.focusX=focus.x;residents.focusZ=focus.z;const closest=residents.map(r=>({r,d:Math.hypot(r.group.position.x-focus.x,r.group.position.z-focus.z)})).filter(e=>e.d<105).sort((a,b)=>a.d-b.d).slice(0,maxVisible),visible=new Set(closest.map(e=>e.r));for(const r of residents){r.group.visible=visible.has(r);r.shown=r.group.visible;}for(const {r,d}of closest)r.root.traverse(o=>{if(o.isMesh)o.castShadow=d<38;});}
 for(const r of residents)if(r.shown)r.mixer.update(dt);
}
